@@ -0,0 +1,40 @@
+// API keys, role permissions and the audit log of data-changing requests.
+import { AppError } from "../errors.js";
+
+const COOK_WRITES = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** Finds the API key for a Bearer authorization header, or throws unauthorized. */
+export function authenticate(store, header) {
+  if (typeof header !== "string") throw new AppError("unauthorized");
+  const m = /^Bearer\s+(\S+)$/i.exec(header.trim());
+  if (!m) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Checks that `role` may call `method` on `path`, or throws forbidden. */
+export function authorize(role, method, path) {
+  if (role === "manager") return;
+  if (method === "GET" && path !== "/audit" && (role === "viewer" || role === "cook")) return;
+  if (role === "cook" && method === "POST" && COOK_WRITES.some((re) => re.test(path))) return;
+  throw new AppError("forbidden");
+}
+
+/** Appends an audit entry for a request that changed data. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse().sort((a, b) => b.at.localeCompare(a.at));
+}
